import React from 'react';
import { BrowserRouter as Router,Route, Routes } from "react-router-dom";
import WeatherPage from "./WeatherPage";
import Nav from "./Nav";
function App(){
    return (
      <Router>
        <div>
            <Routes>
                <Route exact path="/">
                    <WeatherPage />
                </Route>
            </Routes>

            <Nav/>
        </div>
      </Router>
    );
}


export default App;
